package com.aoo.bcg.gamespi.fsm;
import com.aoo.bcg.gamespi.time.OperationDeadline;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class LivenessValidatorTest{enum Event{SETTLE,FINISH}@Test void catchesMissingSeatTimerAndTerminalPath(){var validator=new LivenessValidator();var stuck=new CompositeGameState(RoomLifecycleState.PLAYING,RoundLifecycleState.OPERATING,Map.of(0,PlayerLifecycleState.PLAYING),OperationWindowLifecycleState.OPEN,DissolveLifecycleState.NONE);var errors=validator.violations(stuck,OperationDeadline.none(),List.of(),Set.of(RoomLifecycleState.FINISHED));assertTrue(errors.contains("OPEN_OPERATION_WITHOUT_DEADLINE"));assertTrue(errors.contains("NO_TERMINAL_PATH"));var deadline=new OperationDeadline("round-1",0,Instant.now().plusSeconds(10));var edges=List.<StateTransition<RoomLifecycleState,?>>of(new StateTransition<>(RoomLifecycleState.PLAYING,Event.SETTLE,RoomLifecycleState.SETTLING,"roundEnded","settle"),new StateTransition<>(RoomLifecycleState.SETTLING,Event.FINISH,RoomLifecycleState.FINISHED,"settled","finish"));assertTrue(validator.violations(stuck,deadline,edges,Set.of(RoomLifecycleState.FINISHED)).isEmpty());}}
